/// A single dab of the current brush, for the cursor and the panel.
///
/// Rendered by the engine rather than approximated in the frontend, so
/// what the preview shows and what the brush paints cannot drift apart.
/// "it should preview the actual brush like [the layer
/// editors] do. Especially for the textured brushes. Otherwise we are
/// just guessing."
///
/// Returns coverage as bytes so the webview can drop it straight into an
/// ImageData without an image decoder in the middle.
#[tauri::command]
fn brush_tip_preview(
    tip: String,
    size: usize,
    hardness: f32,
    texture_scale: f32,
    texture_depth: f32,
    texture_angle: f32,
) -> Result<tauri::ipc::Response, String> {
    // Raw bytes, not a JSON array: at the 2048 cap a dab is four million
    // values, which as JSON numbers was the slow part.
    let cov = heeler_engine::ops_masks::tip_preview(
        &tip,
        size,
        hardness,
        texture_scale,
        texture_depth,
        texture_angle,
    );
    Ok(tauri::ipc::Response::new(tip_bytes(&cov)))
}

/// Coverage as the bytes the webview drops into an ImageData.
fn tip_bytes(cov: &[f32]) -> Vec<u8> {
    cov.iter().map(|v| (v.clamp(0.0, 1.0) * 255.0).round() as u8).collect()
}

#[tauri::command]
async fn catalog_info(app: tauri::AppHandle) -> Result<CatalogInfo, String> {
    let issued = catalog_generation(&app)?;
    tauri::async_runtime::spawn_blocking(move || -> Result<CatalogInfo, String> {
        let path = active_catalog_path(&app)?;
        with_catalog_at(&app, issued, |c| {
            let s = c.stats().map_err(|e| e.to_string())?;
            Ok(CatalogInfo {
                path: path.to_string_lossy().to_string(),
                images: s.images,
                folders: s.folders,
                collections: s.collections,
                hidden: s.hidden,
                thumbnails: s.thumbnails,
                total_bytes: s.total_bytes,
                irreplaceable_bytes: s.irreplaceable_bytes(),
            })
        })
    })
    .await
    .map_err(|e| e.to_string())?
}

/// Opens the catalog's folder in the system file browser.
