#[derive(Serialize)]
pub struct LutInfo {
    pub title: String,
    pub size: u32,
}

/// LUT inspection: what the chosen .cube actually is, shown beside the
/// filename so a wrong pick is visible before it renders.
#[tauri::command]
async fn lut_info(path: String) -> Result<LutInfo, String> {
    tauri::async_runtime::spawn_blocking(move || -> Result<LutInfo, String> {
        let text = std::fs::read_to_string(&path).map_err(|e| e.to_string())?;
        let lut = heeler_engine::ops_lut::parse_cube(&text)?;
        Ok(LutInfo { title: lut.title, size: lut.size as u32 })
    })
    .await
    .map_err(|e| e.to_string())?
}

/// Everything upstream of (and including) a node, over every wire kind:
/// the part of the graph a bake would capture.
fn upstream_of(ui: &UiGraph, node_id: &str) -> std::collections::HashSet<String> {
    let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
    let mut stack = vec![node_id.to_string()];
    while let Some(at) = stack.pop() {
        if !seen.insert(at.clone()) {
            continue;
        }
        for c in ui.connections.iter().filter(|c| c.to.0 == at) {
            stack.push(c.from.0.clone());
        }
    }
    seen
}

/// Ops whose work is spatial: they read neighbors, geometry, or a
/// position, none of which an identity lattice has. A LUT carries a
/// per-color answer and nothing else, so a branch leaning on any of
/// these is refused with words rather than baked into nonsense.
const LUT_SPATIAL_TYPES: &[&str] = &[
    "heeler.detail",
    "heeler.blur",
    "heeler.high_pass",
    "heeler.sharpen",
    "heeler.unsharp",
    "heeler.denoise",
    "heeler.nlm_denoise",
    "heeler.clarity",
    "heeler.grain",
    "heeler.noise",
    "heeler.vignette",
    "heeler.hot_pixel",
    "heeler.crop_rotate",
    "heeler.lens_correct",
    "heeler.gradient",
    "heeler.fx_shadow",
    "heeler.fx_glow",
    "heeler.fx_bevel",
    "heeler.fx_gradient_overlay",
    "heeler.paint",
    "heeler.clone",
    "heeler.skin_soften",
    "heeler.sharpening",
    "heeler.dof",
    "heeler.flare",
    "heeler.halation",
];

/// Nodes that read the depth plane rather than the pixel: a lattice has
/// no scene to read, so a LUT cannot carry them either.
const LUT_PLANE_TYPES: &[&str] = &["heeler.fog", "heeler.key_light"];

/// Whether a Recolor node selects by the photograph rather than by the
/// pixel's own color: a Depth, Around or Mask row with a curve on it.
/// Those rows read the plane, the surroundings or a mask, none of
/// which a lattice carries.
fn recolor_reads_the_scene(params: &HashMap<String, serde_json::Value>) -> bool {
    let Some(curves) = params.get("curves").and_then(|v| v.as_str()) else { return false };
    let Ok(map) = serde_json::from_str::<serde_json::Value>(curves) else { return false };
    let Some(map) = map.as_object() else { return false };
    map.iter().any(|(k, v)| {
        (k.starts_with("depth_") || k.starts_with("around_") || k.starts_with("mask_"))
            && v.as_array().map(|pts| pts.len() >= 2).unwrap_or(false)
    })
}

/// Whether a Recolor node has an Around row with a curve on it: the
/// only rows that read the averaged surroundings.
fn recolor_reads_around(params: &HashMap<String, serde_json::Value>) -> bool {
    let Some(curves) = params.get("curves").and_then(|v| v.as_str()) else { return false };
    let Ok(map) = serde_json::from_str::<serde_json::Value>(curves) else { return false };
    map.as_object().is_some_and(|m| {
        m.iter().any(|(k, v)| k.starts_with("around_") && v.as_array().map(|pts| pts.len() >= 2).unwrap_or(false))
    })
}

/// Whether a Color Tune or Recolor node's grade reads the smoothed hue
/// lookup, which a box blur over a lattice would smear across unrelated
/// colors. Color Tune's bands always index by it; Recolor only when a
/// hue or sat row, a surface, or the hue-spread mode is in play (the
/// lum, depth, around and mask rows read unsmoothed channels, and the
/// scene readers are refused separately).
fn smoothed_lookup_in_use(n: &UiNode) -> bool {
    let text = |k: &str| n.params.get(k).and_then(|v| v.as_str()).unwrap_or("");
    match n.node_type.as_str() {
        "heeler.color_console" => heeler_engine::ops_console::has_active_bands(text("bands")),
        "heeler.recolor" => heeler_engine::recolor_uses_smoothed_lookup(text("curves"), text("surfaces")),
        _ => false,
    }
}

/// A LUT cannot represent a neighborhood-dependent grade, even when its
/// own small lattice happens to round the smoothing radius to zero.
fn lut_bake_refusal(ui: &UiGraph, node_id: &str, _size: usize) -> Option<String> {
    let up = upstream_of(ui, node_id);
    for n in ui.nodes.iter().filter(|n| up.contains(&n.id) && n.enabled) {
        // A By tone gradient is a function of the pixel's own color
        // alone, as the Gradient Map it replaced was, so it bakes.
        let by_tone = n.node_type == "heeler.gradient" && n.params.get("shape").and_then(|v| v.as_str()) == Some("tone");
        if LUT_SPATIAL_TYPES.contains(&n.node_type.as_str()) && !by_tone {
            return Some(format!(
                "the branch runs through {}, which works on neighboring pixels; a LUT carries color only",
                n.node_type.trim_start_matches("heeler.")
            ));
        }
        if LUT_PLANE_TYPES.contains(&n.node_type.as_str())
            || (n.node_type == "heeler.recolor" && recolor_reads_the_scene(&n.params))
        {
            return Some(format!(
                "the branch runs through {}, which reads the photograph's depth, surroundings or a mask; a LUT carries color only",
                n.node_type.trim_start_matches("heeler.")
            ));
        }
        if matches!(n.node_type.as_str(), "heeler.color_console" | "heeler.recolor") && smoothed_lookup_in_use(n) {
            let smoothing = n
                .params
                .get("smoothing")
                .and_then(|v| v.as_f64())
                .unwrap_or(50.0)
                .clamp(0.0, 100.0)
                / 100.0;
            if smoothing > 0.0 {
                return Some(format!(
                    "the branch runs through {}, whose Smoothing blends what neighboring pixels look like; a LUT cannot store that neighborhood dependence. Set Smoothing to 0 before baking",
                    n.node_type.trim_start_matches("heeler.")
                ));
            }
        }
    }
    if ui
        .connections
        .iter()
        .any(|c| up.contains(&c.to.0) && c.to.1 == "mask")
    {
        return Some("the branch is masked; a LUT applies everywhere or not at all".into());
    }
    None
}

/// The bake itself: an identity lattice pushed through the branch, read
/// back on the LUT node's own axis. The lattice is sRGB-ENCODED values
/// decoded to scene-linear on the way in, and the render is encoded on
/// the way out, because that is exactly the sandwich ops_lut::lut makes
/// around a .cube: apply the baked file through the LUT node and you
/// get the branch back, to lattice resolution.
fn bake_branch_lut(ui: &UiGraph, node_id: &str, size: usize) -> Result<String, String> {
    if !(5..=65).contains(&size) {
        return Err(format!("unreasonable LUT size {size}"));
    }
    if let Some(why) = lut_bake_refusal(ui, node_id, size) {
        return Err(why);
    }
    let name = ui
        .nodes
        .iter()
        .find(|n| n.id == node_id)
        .map(|n| n.node_type.trim_start_matches("heeler.").to_string())
        .ok_or("no such node")?;

    let mut lattice = ImageBuf::new(size * size, size);
    for b in 0..size {
        for g in 0..size {
            for r in 0..size {
                let i = ((b * size * size) + g * size + r) * 4;
                lattice.data[i] = heeler_engine::ops::to_scene(r as f32 / (size - 1) as f32);
                lattice.data[i + 1] = heeler_engine::ops::to_scene(g as f32 / (size - 1) as f32);
                lattice.data[i + 2] = heeler_engine::ops::to_scene(b as f32 / (size - 1) as f32);
                lattice.data[i + 3] = 1.0;
            }
        }
    }

    let registry = Registry::builtin();
    let g = build_graph(ui, &registry)?;
    let lattice = std::sync::Arc::new(lattice);
    let mut sources = HashMap::new();
    for n in ui
        .nodes
        .iter()
        .filter(|n| n.node_type == "heeler.image_source" || n.node_type == "heeler.group")
    {
        sources.insert(
            n.id.clone(),
            SourceImage { image: lattice.clone(), version: 1, measured: false },
        );
    }
    plant_file_sources_full(ui, &mut sources)?;
    // A Catalog node on the branch has no app handle to render through
    // here; the empty pixel keeps the bake from failing outright, and the
    // LUT captures the branch's color work without the second exposure.
    for n in ui.nodes.iter().filter(|n| n.node_type == "heeler.catalog") {
        sources.entry(n.id.clone()).or_insert_with(empty_file_source);
    }
    let mut exec = Executor::new();
    let out = exec.render(&g, node_id, &sources).map_err(|e| e.to_string())?;
    let img = out.as_image().ok_or("the branch ends in a mask, not an image")?;
    if img.width != size * size || img.height != size {
        return Err("the branch changes the frame's geometry; a LUT carries color only".into());
    }

    let mut cube = String::with_capacity(size * size * size * 30);
    cube.push_str(&format!("TITLE \"Heeler bake: {name}\"\n"));
    cube.push_str(&format!("LUT_3D_SIZE {size}\n"));
    for b in 0..size {
        for gch in 0..size {
            for r in 0..size {
                let i = ((b * size * size) + gch * size + r) * 4;
                let enc = |v: f32| heeler_engine::ops::to_display(v.max(0.0)).clamp(0.0, 1.0);
                cube.push_str(&format!(
                    "{:.6} {:.6} {:.6}\n",
                    enc(img.data[i]),
                    enc(img.data[i + 1]),
                    enc(img.data[i + 2])
                ));
            }
        }
    }
    Ok(cube)
}

/// Bake the branch ending at a node into a .cube on disk (proposal §5,
/// the LUT-baking half of the LUT item). Asks where to save, then does
/// the render off the UI thread. None means the user canceled.
#[tauri::command]
async fn bake_lut(
    app: tauri::AppHandle,
    graph: UiGraph,
    node_id: String,
    size: Option<usize>,
) -> Result<Option<String>, String> {
    use tauri_plugin_dialog::DialogExt;
    let Some(fp) = app
        .dialog()
        .file()
        .add_filter("Cube LUT", &["cube"])
        .set_file_name("heeler-bake.cube")
        .blocking_save_file()
    else {
        return Ok(None);
    };
    let path = fp.into_path().map_err(|e| e.to_string())?;
    let _guard = render_lock().lock().await;
    tauri::async_runtime::spawn_blocking(move || {
        let cube = bake_branch_lut(&graph, &node_id, size.unwrap_or(33))?;
        std::fs::write(&path, cube).map_err(|e| e.to_string())?;
        Ok(Some(path.to_string_lossy().to_string()))
    })
    .await
    .map_err(|e| e.to_string())?
}

