    fn recent_catalogs_timed(
        dir: &Path,
        probe: &impl Fn(&Path) -> (Option<PathBuf>, bool),
        log: &impl Fn(String),
    ) -> Result<Vec<RecentCatalog>, String> {
        let total = std::time::Instant::now();
        let t = std::time::Instant::now();
        std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
        let active = active_catalog_in(dir);
        log(format!("recent catalogs: active pointer {:.3}ms path={}", t.elapsed().as_secs_f64() * 1000.0, active.display()));
        let t = std::time::Instant::now();
        let active = std::fs::canonicalize(&active).unwrap_or(active);
        log(format!("recent catalogs: active canonicalize {:.3}ms", t.elapsed().as_secs_f64() * 1000.0));
        let t = std::time::Instant::now();
        let paths = recent_catalogs_in(dir);
        log(format!("recent catalogs: list read {:.3}ms", t.elapsed().as_secs_f64() * 1000.0));
        let out = paths.into_iter().map(|p| {
            let path = PathBuf::from(&p);
            let t = std::time::Instant::now();
            let (canonical, exists) = probe(&path);
            log(format!("recent catalogs: check {:.3}ms exists={exists} path={p}", t.elapsed().as_secs_f64() * 1000.0));
            RecentCatalog {
                name: path.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_else(|| p.clone()),
                active: Some(canonical.is_some_and(|c| c == active)), exists: Some(exists), path: p,
            }
        }).collect();
        log(format!("recent catalogs: total {:.3}ms", total.elapsed().as_secs_f64() * 1000.0));
        Ok(out)
    }

    /// The off-main-thread assertion every batch's source-shape test
    /// runs: the command dispatches asynchronously, its work is on a
    /// worker (spawn_blocking directly, or catalog_command, which is
    /// spawn_blocking plus the generation guard), and no lock is taken
    /// on the async side. A JavaScript mock alone passed against the
    /// old synchronous code and proved nothing, so the shape is pinned
    /// here: the behavior only diverges from synchronous on a slow
    /// disk.
    fn assert_off_the_main_thread(src: &str, name: &str) {
        let signature = format!("async fn {name}(");
        let start = src.find(&signature).unwrap_or_else(|| panic!("{name} must dispatch asynchronously"));
        let body = &src[start..src[start..].find("\n}\n").unwrap() + start];
        let at = ["spawn_blocking", "catalog_command("]
            .iter()
            .filter_map(|m| body.find(m))
            .min()
            .unwrap_or_else(|| panic!("{name} must move its work to a worker"));
        for lock in ["with_session", "with_catalog", "with_catalog_slot"] {
            assert!(!body[..at].contains(lock), "{name} must not hold {lock} on the async side");
        }
    }

    /// Every production source in the crate, concatenated: commands
    /// live in lib.rs, py.rs, agreement.rs and the rest alike, and a
    /// shape test that read only lib.rs would go blind to the rest.
    fn src_all() -> String {
        let src_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut files: Vec<std::path::PathBuf> = std::fs::read_dir(&src_dir)
            .expect("the desktop crate's src directory")
            .map(|e| e.expect("a readable entry").path())
            .filter(|p| p.extension().is_some_and(|x| x == "rs"))
            .collect();
        files.sort();
        let mut out = String::new();
        for path in files {
            out.push_str(&std::fs::read_to_string(&path).expect("a readable source file"));
            out.push('\n');
        }
        out.replace("\r\n", "\n")
    }

