    /// Phase 2b's watch item: open_catalog and create_catalog switch the
    /// active catalog, and a query already queued on the old one must
    /// answer from the catalog it was issued against or fail cleanly,
    /// never from the other. The guard is the slot's generation: every
    /// switch goes through set_active_catalog, which bumps it. Two real
    /// catalog files, so the read side is a real database answer.
    #[test]
    fn a_query_issued_before_a_switch_never_reads_the_new_catalog() {
        let dir = tempfile::tempdir().unwrap();
        let path_a = dir.path().join("a.sqlite");
        let path_b = dir.path().join("b.sqlite");
        let a = Catalog::open(&path_a).unwrap();
        a.add_folder(Path::new("/photos/a")).unwrap();
        let b = Catalog::open(&path_b).unwrap();
        b.add_folder(Path::new("/photos/b")).unwrap();
        b.add_folder(Path::new("/photos/b2")).unwrap();

        let mut slot = CatalogSlot::default();
        slot.catalog = Some(a);
        // A query issued now answers from A, and the same generation
        // passes the guard as often as it is checked while nothing
        // switches.
        let issued = slot.generation;
        slot.check_generation(issued).unwrap();
        let folders: i64 = {
            let c = slot.catalog.as_ref().unwrap();
            let (i, f, co) = c.counts().unwrap();
            let _ = (i, co);
            f
        };
        assert_eq!(folders, 1, "before the switch the query reads catalog A");

        // The switch, as open_catalog performs it: set_active_catalog
        // drops the connection and bumps the generation, then the new
        // connection is installed.
        slot.switched();
        slot.catalog = Some(b);

        // The queued query fails cleanly, and the guard fails BEFORE the
        // catalog is touched, so nothing from B can leak into its answer.
        let refused = slot.check_generation(issued).unwrap_err();
        assert!(refused.contains("run it again"), "the refusal says what to do: {refused}");
        // A query issued against the new generation answers from B.
        slot.check_generation(slot.generation).unwrap();
        let folders: i64 = {
            let c = slot.catalog.as_ref().unwrap();
            let (i, f, co) = c.counts().unwrap();
            let _ = (i, co);
            f
        };
        assert_eq!(folders, 2, "after the switch a fresh query reads catalog B");
    }

    /// The write half of the watch item, closed when the guard became
    /// the default: a set_image_rating that left the frontend before a
    /// switch must not land on the new catalog's row for the same id.
    /// Same slot-level shape as the read test above, with a real rating
    /// write as the payload.
    #[test]
    fn a_rating_issued_before_a_switch_is_refused_and_the_new_catalog_is_untouched() {
        let dir = tempfile::tempdir().unwrap();
        let a = Catalog::open(&dir.path().join("a.sqlite")).unwrap();
        a.add_image("img_1", Path::new("/photos/a/one.nef"), None).unwrap();
        let b = Catalog::open(&dir.path().join("b.sqlite")).unwrap();
        b.add_image("img_1", Path::new("/photos/b/one.nef"), None).unwrap();

        // The write as the command runs it: guard first, row second.
        let rate = |slot: &CatalogSlot, issued: u64| -> Result<(), String> {
            slot.check_generation(issued)?;
            slot.catalog
                .as_ref()
                .expect("an open catalog")
                .set_rating("img_1", 5)
                .map_err(|e| e.to_string())
        };

        let mut slot = CatalogSlot::default();
        slot.catalog = Some(a);
        let issued = slot.generation;
        rate(&slot, issued).unwrap();
        assert_eq!(slot.catalog.as_ref().unwrap().image("img_1").unwrap().rating, 5, "without a switch the rating lands on A");

        slot.switched();
        slot.catalog = Some(b);
        let refused = rate(&slot, issued).unwrap_err();
        assert!(refused.contains("run it again"), "the refusal says what to do: {refused}");
        assert_eq!(slot.catalog.as_ref().unwrap().image("img_1").unwrap().rating, 0, "the new catalog's row was never touched");

        // Issued against the new generation, the same write lands on B.
        rate(&slot, slot.generation).unwrap();
        assert_eq!(slot.catalog.as_ref().unwrap().image("img_1").unwrap().rating, 5, "a fresh write rates B's own row");
    }

    static RECENT_PROBE_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

    #[test]
    fn recent_names_do_not_probe_and_an_absent_catalog_stays_listed() {
        let _guard = RECENT_PROBE_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("absent.sqlite");
        std::fs::write(dir.path().join(RECENT_CATALOGS_FILE), serde_json::to_vec(&vec![path.to_string_lossy()]).unwrap()).unwrap();
        let rows = recent_catalog_names(dir.path(), RECENT_CATALOGS_KEPT);
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].exists, None);
        assert_eq!(recent_catalog_probe(&path), (None, false), "the probe itself answers absent");
        // Through the bounded check: an answer later than its deadline is
        // "unknown" by design, and a test binary running hundreds of tests
        // at once can starve the worker past it (a Windows run took
        // 251 ms). Unknown is not wrong, so a few tries are allowed; the
        // first answer that arrives must be "absent".
        let mut answer = None;
        for _ in 0..8 {
            let t = std::time::Instant::now();
            let checked = check_recent_catalogs(rows.clone(), std::sync::Arc::new(|p| (recent_catalog_probe(Path::new(p)).1, false)));
            eprintln!("absent catalog check {:.3}ms", t.elapsed().as_secs_f64() * 1000.0);
            assert_eq!(checked.len(), 1);
            answer = checked[0].exists;
            if answer.is_some() {
                break;
            }
        }
        assert_eq!(answer, Some(false), "an absent catalog stays listed and reads as absent");
        assert!(!path.exists(), "checking never opens or creates a catalog");
    }

    /// A Windows run (2026-10-02) handed a renamed recipe back as
    /// `\\?\C:\...` while the list named it `C:\...`. The usual form is
    /// what a Windows user reads and what the rest of the app stores.
    #[test]
    fn verbatim_windows_paths_come_back_in_their_usual_form() {
        assert_eq!(strip_verbatim(r"\\?\C:\Users\user\Looks\Dreamy.heelerrecipe").as_deref(), Some(r"C:\Users\user\Looks\Dreamy.heelerrecipe"));
        assert_eq!(strip_verbatim(r"\\?\UNC\nas\photos\a.dng").as_deref(), Some(r"\\nas\photos\a.dng"));
        assert_eq!(strip_verbatim(r"\\?\d:\").as_deref(), Some(r"d:\"));
        // Already usual, or verbatim with no usual form: left alone.
        assert_eq!(strip_verbatim(r"C:\Users\user"), None);
        assert_eq!(strip_verbatim("/Users/user/Pictures"), None);
        assert_eq!(strip_verbatim(r"\\?\Volume{0b1c2d3e-0000-0000-0000-000000000000}\x"), None);
        assert_eq!(strip_verbatim(r"\\?\C:"), None);
        assert_eq!(strip_verbatim(r"\\?\C:\shoot.\a.dng"), None, "a trailing dot is dropped by the usual form");
        assert_eq!(strip_verbatim(r"\\?\C:\shoot \a.dng"), None, "so is a trailing space");
        assert_eq!(strip_verbatim(&format!(r"\\?\C:\{}", "a".repeat(300))), None, "too long for the usual form");
        // Everywhere but Windows, plain_path is the identity.
        let p = PathBuf::from("/private/var/x");
        assert_eq!(plain_path(p.clone()), p);
        if cfg!(windows) {
            assert_eq!(plain_path(PathBuf::from(r"\\?\C:\x")), PathBuf::from(r"C:\x"));
        } else {
            assert_eq!(plain_path(PathBuf::from(r"\\?\C:\x")), PathBuf::from(r"\\?\C:\x"), "a legal (odd) file name elsewhere");
        }
    }

    #[test]
    fn a_slow_recent_path_is_unknown_without_holding_the_other_entries() {
        let _guard = RECENT_PROBE_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let rows = (0..40).map(|i| RecentCatalog {
            path: i.to_string(), name: i.to_string(), exists: None, active: None,
        }).collect();
        let (release, wait) = std::sync::mpsc::channel();
        let wait = std::sync::Mutex::new(wait);
        let (finished, done) = std::sync::mpsc::channel();
        let t = std::time::Instant::now();
        let rows = check_recent_catalogs(rows, std::sync::Arc::new(move |p| {
            if p == "0" {
                wait.lock().unwrap().recv().unwrap();
                finished.send(()).unwrap();
            }
            (true, false)
        }));
        eprintln!("bounded recent batch {:.3}ms", t.elapsed().as_secs_f64() * 1000.0);
        release.send(()).unwrap();
        done.recv_timeout(std::time::Duration::from_secs(1)).unwrap();
        // The probe signals before its worker drops the permit. Keep
        // the next pool test from starting during that final handoff.
        let settled = std::time::Instant::now() + std::time::Duration::from_secs(1);
        while RECENT_CHECKS_RUNNING.load(std::sync::atomic::Ordering::Acquire) != 0 && std::time::Instant::now() < settled {
            std::thread::yield_now();
        }
        assert_eq!(RECENT_CHECKS_RUNNING.load(std::sync::atomic::Ordering::Acquire), 0);
        // Four times the room on Linux, which runs on a slower VM.
        let slack = if cfg!(target_os = "linux") { 4 } else { 1 };
        assert!(t.elapsed() < std::time::Duration::from_secs(slack));
        assert_eq!(rows[0].exists, None);
        assert!(rows[1..].iter().all(|r| r.exists == Some(true)), "one blocked row must not strand later batches");
    }

    /// The dialog lists the whole history, which is longer than the
    /// pool. Every row must still get an answer: the first pass took a
    /// permit per row in one go, so with forty rows and eight permits
    /// the last thirty-two were skipped and read "still checking" for
    /// as long as the dialog was open.
    #[test]
    fn every_row_of_a_long_list_is_checked_even_though_the_pool_is_small() {
        let _guard = RECENT_PROBE_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let rows: Vec<RecentCatalog> = (0..RECENT_CATALOGS_HISTORY).map(|i| RecentCatalog {
            path: format!("/p/{i}.sqlite"), name: format!("{i}.sqlite"), exists: None, active: None,
        }).collect();
        assert!(rows.len() > RECENT_CHECK_WORKERS, "the list has to outrun the pool for this to mean anything");
        let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let heard = seen.clone();
        let rows = check_recent_catalogs(rows, std::sync::Arc::new(move |p| {
            heard.lock().unwrap().push(p.to_string());
            (true, false)
        }));
        assert_eq!(seen.lock().unwrap().len(), RECENT_CATALOGS_HISTORY, "every path probed once");
        for (i, row) in rows.iter().enumerate() {
            assert_eq!(row.exists, Some(true), "row {i} went unanswered");
        }
    }

    #[test]
    fn saturated_recent_workers_are_bounded_and_release_their_permits() {
        let _guard = RECENT_PROBE_TEST_LOCK.lock().unwrap_or_else(|e| e.into_inner());
        let rows = || (0..8).map(|i| RecentCatalog {
            path: i.to_string(), name: i.to_string(), exists: None, active: None,
        }).collect();
        let gate = std::sync::Arc::new((std::sync::Mutex::new(false), std::sync::Condvar::new()));
        let blocked = gate.clone();
        let first = check_recent_catalogs(rows(), std::sync::Arc::new(move |_| {
            let (lock, wake) = &*blocked;
            let _released = wake.wait_while(lock.lock().unwrap(), |released| !*released).unwrap();
            (true, false)
        }));
        let running = RECENT_CHECKS_RUNNING.load(std::sync::atomic::Ordering::Acquire);
        let second = check_recent_catalogs(rows(), std::sync::Arc::new(|_| panic!("no permit available")));
        *gate.0.lock().unwrap() = true;
        gate.1.notify_all();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(1);
        while RECENT_CHECKS_RUNNING.load(std::sync::atomic::Ordering::Acquire) != 0 && std::time::Instant::now() < deadline {
            std::thread::yield_now();
        }
        assert_eq!(running, RECENT_CHECK_WORKERS);
        assert!(first.iter().chain(&second).all(|r| r.exists.is_none()));
        assert_eq!(RECENT_CHECKS_RUNNING.load(std::sync::atomic::Ordering::Acquire), 0);
        let recovered = check_recent_catalogs(rows(), std::sync::Arc::new(|_| (true, false)));
        assert!(recovered.iter().all(|r| r.exists == Some(true)));
    }

