    #[test]
    fn source_versions_keep_the_tiers_apart() {
        // The same photo at the rest edge, the gesture edge and a memory
        // fallback are three sources to the executor, and the sensor a
        // fourth; the same edge twice is the same source (a cache hit).
        let base = "photo|opts";
        let rest = super::source_version(base, false, 2048);
        let gesture = super::source_version(base, false, 1024);
        let fallback = super::source_version(base, false, 512);
        let sensor = super::source_version(base, true, 6000);
        assert_ne!(rest, gesture);
        assert_ne!(rest, fallback);
        assert_ne!(gesture, fallback);
        assert_ne!(rest, sensor);
        assert_eq!(rest, super::source_version(base, false, 2048));
    }

    use super::*;

    /// The gamut scan behind the warning badge: what counts as out and
    /// what counts as headed for the clip.
    #[test]
    fn preview_retries_smaller_tiers_and_reports_one_notice() {
        let mut tried = Vec::new();
        let (value, notice) = retry_preview(None, |tier| {
            tried.push(tier);
            if tier == Some(1024) { Ok(42) } else { Err("Not enough memory for preview".into()) }
        }).unwrap();
        assert_eq!(tried, vec![None, Some(4096), Some(2048), Some(1024)]);
        assert_eq!(value, 42);
        let notice = notice.unwrap();
        assert!(notice.contains("1024"));
        assert!(notice.contains("1:1 view"), "a fallen 1:1 view says so: {notice}");
        // A preview that was never 1:1 just says it got smaller.
        let (_, notice) = retry_preview(Some(4096), |tier| if tier == Some(2048) { Ok(1) } else { Err("Not enough memory for preview".into()) }).unwrap();
        let notice = notice.unwrap();
        assert!(notice.starts_with("Preview reduced to 2048"), "{notice}");
        assert!(!notice.contains("1:1"));
        let mut calls = 0;
        let error = retry_preview(Some(2048), |_| { calls += 1; Err::<(), _>("file is missing".into()) }).unwrap_err();
        assert_eq!(calls, 1);
        assert_eq!(error, "file is missing");
    }

