    #[test]
    fn review_mask_kinds_match_the_export_crop() {
        let registry = Registry::builtin();
        let cases = [
            ("heeler.brush_mask", serde_json::json!({"strokes": "[{\"points\":[[0.4,0.4],[0.6,0.6]],\"radius\":0.2}]"})),
            ("heeler.radial_mask", serde_json::json!({"radius": 0.3, "feather": 0.3})),
            ("heeler.linear_mask", serde_json::json!({"angle": 35, "position": 0.5, "span": 0.4})),
            ("heeler.smart_mask", serde_json::json!({})),
            ("heeler.matte_mask", serde_json::json!({})),
            ("heeler.selection_mask", serde_json::json!({"regions": "[{\"kind\":\"range\",\"channel\":\"depth\",\"lo\":0.2,\"hi\":0.7,\"soft\":0.1,\"op\":\"replace\"}]"})),
        ];
        for angle in [0.0, 3.0] {
            for (kind, params) in &cases {
                let (mut ui, mut sources, source) = portrait_mask_rig(angle, true);
                let node = ui.nodes.iter_mut().find(|n| n.id == "layer_1_mask").unwrap();
                node.node_type = (*kind).into();
                node.params = serde_json::from_value(params.clone()).unwrap();
                node.params.insert("depth_on".into(), serde_json::json!(true));
                let plane = sources["depthmap@depth"].image.clone();
                // A nonuniform model matte, owned by this test and
                // already in the user's cropped frame.
                sources.insert("layer_1_mask".into(), SourceImage { image: plane, version: 3, measured: false });
                let s = conformed(&ui, &sources, source);
                let whole = Executor::new().render(&build_graph(&ui, &registry).unwrap(), "output", &s).unwrap();
                let whole = whole.as_image().unwrap();
                let exported = render_export(&ui, sources["src"].image.clone(), &s).unwrap();
                assert_eq!(whole.data, exported.data, "{kind}: export entry point");
                let (slice, rect) = inject_roi_frame(&ui, [0.1, 0.3, 0.8, 0.4], source).unwrap();
                let s = conformed(&slice, &sources, source);
                let g = build_graph(&slice, &registry).unwrap();
                let actual = Executor::new().render(&g, "output", &s).unwrap();
                let expected = heeler_engine::crop_rotate_buf(whole, 0.0, 0.0, rect.map(|v| v as f32));
                let actual = actual.as_image().unwrap();
                assert_eq!((actual.width, actual.height), (expected.width, expected.height), "{kind}");
                let err = actual.data.iter().zip(&expected.data).map(|(a,b)| (a-b).abs()).fold(0.0f32, f32::max);
                assert!(err < 0.0001, "{kind}, angle {angle}: export crop error {err}");
                let terminal = mask_view_terminal(&slice, "layer_1_mask", &mut Some(rect));
                let mask = Executor::new().render(&g, &terminal, &s).unwrap();
                assert_eq!((mask.as_mask().unwrap().width, mask.as_mask().unwrap().height), (expected.width, expected.height), "{kind} eye geometry");
            }
        }
    }

    #[test]
    fn review_overlay_colors_and_opacities_follow_displayed_coverage() {
        let shown = [0.0f32, 0.25, 0.5, 0.75, 1.0];
        let mut mask = MaskBuf::new(shown.len(), 1);
        mask.data = shown.map(heeler_io::srgb_to_linear).to_vec();
        let mask = Value::Mask(Arc::new(mask));
        let mut photo = ImageBuf::new(shown.len(), 1);
        for x in 0..shown.len() { photo.set_pixel(x, 0, [0.1, 0.3, 0.6, 0.7]); }
        for color in ["red", "magenta", "cyan", "green"] {
            for opacity in [0.0, 0.25, 0.5, 1.0] {
                let tint = overlay_tint(Some(color)).map(heeler_io::linear_to_srgb);
                let out = red_overlay(&photo, &mask, opacity, Some(color)).unwrap();
                for (x, coverage) in shown.into_iter().enumerate() {
                    let a = coverage * opacity;
                    for c in 0..3 {
                        let want = heeler_io::linear_to_srgb(photo.pixel(x, 0)[c]) * (1.0 - a) + tint[c] * a;
                        let got = heeler_io::linear_to_srgb(out.pixel(x, 0)[c]);
                        assert!((want-got).abs() < 0.0001, "{color} opacity {opacity} gray {coverage}");
                    }
                    assert_eq!(out.pixel(x, 0)[3], 0.7);
                }
            }
        }
    }

    /// The planted plane conformed to a graph the way the preview does
    /// it: the crops the Depth Map sits behind, less its seat's own.
    fn conformed(ui: &UiGraph, sources: &HashMap<String, SourceImage>, frame: (usize, usize)) -> HashMap<String, SourceImage> {
        let mut out = sources.clone();
        let seat: std::collections::HashSet<String> = ["crop".to_string()].into_iter().collect();
        conform_rasters_to_geometry(ui, &mut out, &["depthmap@depth".to_string()], Some(frame), &seat);
        out
    }

    fn mask_of(v: Value) -> MaskBuf {
        v.as_mask().expect("a mask").as_ref().clone()
    }

    /// The mask view's frame has the photograph's dimensions and lines
    /// up pixel for pixel, at Fit and in a 1:1 slice, for a Color Set's
    /// range and a layer's mask with its Depth mask on, straight and
    /// straightened.
    #[test]
    fn a_mask_view_slice_is_the_whole_masks_crop_pixel_for_pixel() {
        let registry = Registry::builtin();
        for angle in [0.0, 3.0] {
            for set_depth in [false, true] {
                let (ui, sources, source) = portrait_mask_rig(angle, set_depth);
                let whole_sources = conformed(&ui, &sources, source);
                let g_whole = build_graph(&ui, &registry).unwrap();
                let photo = Executor::new().render(&g_whole, "output", &whole_sources).unwrap();
                let photo = photo.as_image().unwrap().clone();
                // A vertical slice, the shape of the owner's view: most of
                // the width, less than half the height.
                let (roi_ui, actual) = inject_roi_frame(&ui, [0.1, 0.3, 0.8, 0.4], source).unwrap();
                let roi_sources = conformed(&roi_ui, &sources, source);
                let g_roi = build_graph(&roi_ui, &registry).unwrap();
                let (pw, ph, x0, y0) = heeler_engine::frame_window(photo.width, photo.height, actual.map(|v| v as f32));
                for id in ["cset1_mask", "layer_1_mask"] {
                    let whole = mask_of(Executor::new().render(&g_whole, id, &whole_sources).unwrap());
                    // Fit: the mask frame is the photograph's frame.
                    assert_eq!((whole.width, whole.height), (photo.width, photo.height), "{id} at Fit, angle {angle}");
                    let mut rect = Some(actual);
                    let terminal = mask_view_terminal(&roi_ui, id, &mut rect);
                    assert_eq!(rect, Some(actual), "{id}: the slice reports its own rect");
                    let sliced = mask_of(Executor::new().render(&g_roi, &terminal, &roi_sources).unwrap());
                    assert_eq!((sliced.width, sliced.height), (pw, ph), "{id} slice size, angle {angle} set_depth {set_depth}");
                    // The frame the viewer places the patch in, as the
                    // render reports it: the photograph's.
                    let r = rect.unwrap();
                    assert_eq!(
                        ((sliced.width as f64 / r[2]).round() as usize, (sliced.height as f64 / r[3]).round() as usize),
                        (photo.width, photo.height),
                        "{id} reported frame"
                    );
                    for y in 0..ph {
                        for x in 0..pw {
                            let a = sliced.data[y * pw + x];
                            let b = whole.data[(y + y0) * whole.width + (x + x0)];
                            assert!((a - b).abs() < 1e-4, "{id} angle {angle} set_depth {set_depth}: slice ({x},{y}) {a} != whole {b}");
                        }
                    }
                }
            }
        }
    }

    /// What a mask eye shows is what the adjustment multiplies by: the
    /// preview's mask node (or its slice) against the mask the layer's
    /// and the set's nodes actually consume, derived from their output
    /// (out = in + (processed - in) * mask). With the set's Depth mask
    /// on, the range is multiplied by the plane's nearness exactly
    /// once: "darker" is the product, never the plane applied twice.
    #[test]
    fn a_mask_eye_shows_the_mask_the_adjustment_consumes() {
        let registry = Registry::builtin();
        for set_depth in [false, true] {
            let (ui, sources, source) = portrait_mask_rig(3.0, set_depth);
            let (roi_ui, actual) = inject_roi_frame(&ui, [0.1, 0.3, 0.8, 0.4], source).unwrap();
            for (graph, rect) in [(&ui, None), (&roi_ui, Some(actual))] {
                let s = conformed(graph, &sources, source);
                let g = build_graph(graph, &registry).unwrap();
                for (mask, adj) in [("cset1_mask", "cset1_grade"), ("layer_1_mask", "layer_1_adj")] {
                    let terminal = match rect {
                        Some(r) => mask_view_terminal(graph, mask, &mut Some(r)),
                        None => mask.to_string(),
                    };
                    let shown = mask_of(Executor::new().render(&g, &terminal, &s).unwrap());
                    let feed = |port: &str| graph.connections.iter().find(|c| c.to.0 == adj && c.to.1 == port).unwrap().from.0.clone();
                    let input = Executor::new().render(&g, &feed("in"), &s).unwrap().as_image().unwrap().clone();
                    let out = Executor::new().render(&g, adj, &s).unwrap().as_image().unwrap().clone();
                    let mut bare = graph.clone();
                    bare.connections.retain(|c| !(c.to.0 == adj && c.to.1 == "mask"));
                    let processed = Executor::new().render(&build_graph(&bare, &registry).unwrap(), adj, &s).unwrap();
                    let processed = processed.as_image().unwrap().clone();
                    assert_eq!((shown.width, shown.height), (input.width, input.height), "{mask} shown at the size its node consumes, slice {}", rect.is_some());
                    let mut checked = 0;
                    for (i, m) in shown.data.iter().enumerate() {
                        for c in 0..3 {
                            let (a, p, o) = (input.data[i * 4 + c], processed.data[i * 4 + c], out.data[i * 4 + c]);
                            if (p - a).abs() > 1e-3 {
                                let consumed = (o - a) / (p - a);
                                assert!((consumed - m).abs() < 2e-3, "{mask} slice {} px {i}: shown {m}, consumed {consumed}", rect.is_some());
                                checked += 1;
                            }
                        }
                    }
                    assert!(checked > 100, "{mask}: the adjustment moved enough pixels to read its mask ({checked})");
                }
                // The set's Depth mask: the range times nearness, once.
                if set_depth && rect.is_none() {
                    let mut plain = graph.clone();
                    for n in plain.nodes.iter_mut().filter(|n| n.id == "cset1_mask") {
                        n.params.insert("depth_on".into(), serde_json::json!(0));
                    }
                    let range = mask_of(Executor::new().render(&build_graph(&plain, &registry).unwrap(), "cset1_mask", &s).unwrap());
                    let with_depth = mask_of(Executor::new().render(&g, "cset1_mask", &s).unwrap());
                    let plane = s["depthmap@depth"].image.clone();
                    assert_eq!((plane.width, plane.height), (range.width, range.height));
                    let mut darker = 0;
                    for i in 0..range.data.len() {
                        let near = 1.0 - plane.data[i * 4];
                        assert!((with_depth.data[i] - range.data[i] * near).abs() < 1e-5, "px {i}: {} != {} x {near}", with_depth.data[i], range.data[i]);
                        if range.data[i] > 0.05 && near < 0.9 {
                            darker += 1;
                        }
                    }
                    assert!(darker > 50, "the plane darkens a real share of the selection ({darker})");
                }
            }
        }
    }

    /// A hand-edited graph with its own node named `__roi_m0` on the
    /// mask's wire (the frontend never writes the id): the mask view's
    /// terminal is the splice's marked wrapper, never the user's node.
    #[test]
    fn the_mask_view_takes_only_the_splices_marked_wrapper() {
        let node = |id: &str, ty: &str| UiNode {
            id: id.into(),
            node_type: ty.into(),
            enabled: true,
            params: HashMap::new(),
        };
        let wire = |a: &str, b: &str, port: &str| UiConnection {
            from: (a.into(), "out".into()),
            to: (b.into(), port.into()),
        };
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                node("src", "heeler.image_source"),
                node("crop", "heeler.crop_rotate"),
                node("mask", "heeler.range_mask"),
                node("__roi_m0", "heeler.mask_crop"),
                node("exposure", "heeler.exposure"),
            ],
            connections: vec![
                wire("src", "crop", "in"),
                wire("crop", "exposure", "in"),
                wire("src", "mask", "in"),
                // The user's own wrapper-named node, on the wire ahead
                // of the layer's mask port so a name match finds it
                // first.
                wire("mask", "__roi_m0", "in"),
                wire("mask", "exposure", "mask"),
            ],
        };
        let (roi_ui, _) = inject_roi_px(&ui, [0.25, 0.25, 0.5, 0.5], None).unwrap();
        let wrapper = spliced_mask_wrapper(&roi_ui, "mask").expect("the splice wrapped the mask's wire");
        let marked = roi_ui
            .nodes
            .iter()
            .find(|n| n.id == wrapper)
            .and_then(|n| n.params.get(SPLICED_MARK))
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        assert!(marked, "the terminal is the splice's marked wrapper, got {wrapper}");
        assert_ne!(wrapper, "__roi_m0", "the user's unmarked node is not the terminal");
    }

    /// A reduced render carries the pixel scale on every node, the
    /// buffer's short side over the photograph's; the full frame and an
    /// unknown photograph carry nothing, and the scale never exceeds 1.
    #[test]
    fn a_reduced_render_carries_the_pixel_scale() {
        let preview = ImageBuf::new(1280, 1920);
        assert!((px_scale_for(&preview, Some(4016.0)) - 1280.0 / 4016.0).abs() < 1e-6);
        assert_eq!(px_scale_for(&preview, None), 1.0);
        assert_eq!(px_scale_for(&ImageBuf::new(4016, 6024), Some(4016.0)), 1.0);
        assert_eq!(px_scale_for(&ImageBuf::new(5000, 7000), Some(4016.0)), 1.0);
        let ui = UiGraph {
            graph_id: "scale".into(),
            nodes: vec![
                UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                UiNode { id: "blur".into(), node_type: "heeler.blur".into(), enabled: true, params: HashMap::from([("radius".into(), serde_json::json!(35))]) },
            ],
            connections: vec![],
        };
        let scaled = inject_px_scale(&ui, 0.3187);
        for n in &scaled.nodes {
            assert_eq!(n.params.get("px_scale").and_then(|v| v.as_f64()), Some(0.3187), "{}", n.id);
        }
        assert_eq!(scaled.nodes[1].params.get("radius").and_then(|v| v.as_f64()), Some(35.0));
        assert!(inject_px_scale(&ui, 1.0).nodes.iter().all(|n| !n.params.contains_key("px_scale")));
    }

    /// A render token is canceled by name, read by the render's stop
    /// flag, and forgotten when the render returns, so a late cancel of
    /// a finished render marks nothing for the next one.
    #[test]
    fn a_render_token_is_cancelled_by_name_and_forgotten_after() {
        let token = "settle:test:1";
        let guard = RenderToken::start(token.into()).unwrap();
        assert!(!render_cancelled(token));
        tauri::async_runtime::block_on(cancel_render(token.into())).unwrap();
        assert!(render_cancelled(token));
        assert!(!render_cancelled("settle:test:2"));
        drop(guard);
        assert!(!render_cancelled(token));
    }

    /// The Detail review's fix 8, redone: Texture, Clarity and Local
    /// contrast are shares of the frame's short side, so a 1:1 slice
    /// hands them the rect (the frame's size follows from it) and grows
    /// the patch by their reach, rather than falling back to a whole
    /// frame render at every 1:1 zoom.
    /// Color Tune's and Recolor's lookup smoothing is a share of the
    /// frame's short side: the slice hands them its rect and grows by
    /// the smoothing's reach, and Recolor's Around field, when a curve
    /// reads it, grows it by its own (the 26.3.2 Color Tune review).
    #[test]
    fn hue_lookups_ride_the_slice_with_their_margin() {
        for kind in ["heeler.color_console", "heeler.recolor"] {
            let mut ui = UiGraph {
                graph_id: "tune_roi".into(),
                nodes: vec![
                    UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                    UiNode { id: "effect".into(), node_type: kind.into(), enabled: true, params: HashMap::from([("smoothing".into(), serde_json::json!(100))]) },
                    UiNode { id: "output".into(), node_type: "heeler.output".into(), enabled: true, params: HashMap::new() },
                ],
                connections: vec![
                    UiConnection { from: ("src".into(), "out".into()), to: ("effect".into(), "in".into()) },
                    UiConnection { from: ("effect".into(), "out".into()), to: ("output".into(), "in".into()) },
                ],
            };
            let patch = [0.25, 0.25, 0.2, 0.2];
            let (sliced, grown) = inject_roi_px(&ui, patch, Some(4000.0)).unwrap();
            let effect = sliced.nodes.iter().find(|n| n.id == "effect").unwrap();
            assert!(effect.params.get("roi_w").is_some(), "{kind} was not handed its rect");
            // 2% of 4000 is an 80 px box, one more for the sample.
            assert!((patch[0] - grown[0] - 81.0 / 4000.0).abs() < 1e-9, "{kind}: grew {}", patch[0] - grown[0]);
            ui.nodes[1].params.insert("smoothing".into(), serde_json::json!(0));
            assert_eq!(inject_roi_px(&ui, patch, Some(4000.0)).unwrap().1, patch, "{kind}: no smoothing reads no neighbors");
            // The rect reaches the engine through build_graph.
            let g = build_graph(&sliced, &Registry::builtin()).unwrap();
            assert!(g.node("effect").unwrap().params.contains_key("roi_w"), "{kind}: build_graph dropped the rect");
        }
        // Recolor reading its surroundings at the widest reach: the slice
        // grows by half the frame each way, out to the frame's edges.
        let mut params = HashMap::from([("smoothing".to_string(), serde_json::json!(0)), ("around_radius".to_string(), serde_json::json!(50))]);
        params.insert("curves".into(), serde_json::json!(r#"{"around_hue":[[0,0.5],[1,0.6]]}"#));
        let ui = UiGraph {
            graph_id: "around".into(),
            nodes: vec![
                UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                UiNode { id: "effect".into(), node_type: "heeler.recolor".into(), enabled: true, params },
                UiNode { id: "output".into(), node_type: "heeler.output".into(), enabled: true, params: HashMap::new() },
            ],
            connections: vec![
                UiConnection { from: ("src".into(), "out".into()), to: ("effect".into(), "in".into()) },
                UiConnection { from: ("effect".into(), "out".into()), to: ("output".into(), "in".into()) },
            ],
        };
        let grown = inject_roi_px(&ui, [0.25, 0.25, 0.2, 0.2], Some(4000.0)).map(|(_, r)| r);
        assert!(grown.is_none_or(|r| r[0] == 0.0 && r[1] == 0.0 && r[2] >= 0.95 - 1e-9), "Around's reach must reach the edges: {grown:?}");
    }

    #[test]
    fn frame_relative_detail_rides_the_slice_with_its_margin() {
        for kind in ["heeler.detail", "heeler.clarity", "heeler.standard_color"] {
            let mut ui = UiGraph {
                graph_id: "detail_roi".into(),
                nodes: vec![
                    UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                    UiNode { id: "effect".into(), node_type: kind.into(), enabled: true, params: HashMap::new() },
                    UiNode { id: "output".into(), node_type: "heeler.output".into(), enabled: true, params: HashMap::new() },
                ],
                connections: vec![
                    UiConnection { from: ("src".into(), "out".into()), to: ("effect".into(), "in".into()) },
                    UiConnection { from: ("effect".into(), "out".into()), to: ("output".into(), "in".into()) },
                ],
            };
            let patch = [0.25, 0.25, 0.2, 0.2];
            let (plain, rect) = inject_roi_px(&ui, patch, Some(4000.0)).unwrap();
            assert_eq!(rect, patch, "{kind} idle grows nothing");
            // The op gets its rect whether or not it is active, so the
            // frame's size is known to it.
            let effect = plain.nodes.iter().find(|n| n.id == "effect").unwrap();
            assert_eq!(effect.params.get("roi_w").and_then(|v| v.as_f64()), Some(0.2), "{kind} was not handed its rect");
            for param in if kind == "heeler.clarity" { vec!["texture", "clarity", "local_contrast"] } else { vec!["texture", "clarity"] } {
                ui.nodes[1].params = HashMap::from([(param.into(), serde_json::json!(50))]);
                let (_, grown) = inject_roi_px(&ui, patch, Some(4000.0)).unwrap();
                assert!(grown[0] < patch[0] && grown[2] > patch[2], "{kind}/{param} must grow the patch by its reach: {grown:?}");
                // Local contrast reads farthest: 10/1365 of 4000 is a sigma
                // of 29, a box of 51, two passes and one, 104 px of 4000.
                let expect = heeler_engine::detail_reach(4000.0, [param == "texture", param == "clarity", param == "local_contrast"]) as f64;
                assert!((patch[0] - grown[0] - expect).abs() < 1e-6, "{kind}/{param}: grew {} against the engine's {expect}", patch[0] - grown[0]);
            }
            ui.nodes[1].enabled = false;
            assert_eq!(inject_roi_px(&ui, patch, Some(4000.0)).unwrap().1, patch);
            ui.nodes[1].enabled = true;
            ui.nodes[1].params = HashMap::from([("dehaze".into(), serde_json::json!(50))]);
            assert_eq!(inject_roi_px(&ui, patch, Some(4000.0)).unwrap().1, patch, "{kind}: dehaze reads no neighbors");
        }
    }

    #[test]
    fn inject_roi_hands_paint_nodes_the_rect() {
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                UiNode { id: "crop".into(), node_type: "heeler.crop_rotate".into(), enabled: true, params: HashMap::new() },
                UiNode { id: "p1".into(), node_type: "heeler.paint".into(), enabled: true, params: HashMap::new() },
                UiNode { id: "output".into(), node_type: "heeler.output".into(), enabled: true, params: HashMap::new() },
            ],
            connections: vec![
                UiConnection { from: ("src".into(), "out".into()), to: ("crop".into(), "in".into()) },
                UiConnection { from: ("crop".into(), "out".into()), to: ("p1".into(), "in".into()) },
                UiConnection { from: ("p1".into(), "out".into()), to: ("output".into(), "in".into()) },
            ],
        };
        let (out, _) = inject_roi_px(&ui, [0.1, 0.2, 0.3, 0.4], None).unwrap();
        let p1 = out.nodes.iter().find(|n| n.id == "p1").unwrap();
        assert_eq!(p1.params.get("roi_x").and_then(|v| v.as_f64()), Some(0.1));
        assert_eq!(p1.params.get("roi_h").and_then(|v| v.as_f64()), Some(0.4));
    }

    #[test]
    fn a_clones_source_is_pulled_into_the_patch() {
        // Cloning at 1:1 reads pixels from elsewhere in the frame. If
        // the patch held only the viewport, those reads would land off
        // the edge and the repair would disappear at 1:1 while looking
        // right in fit view.
        let strokes = r#"[{"points":[[0.6,0.6]],"radius":0.05,"src_dx":-0.2,"src_dy":0.1}]"#;
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                UiNode { id: "crop".into(), node_type: "heeler.crop_rotate".into(), enabled: true, params: HashMap::new() },
                UiNode {
                    id: "cl".into(),
                    node_type: "heeler.clone".into(),
                    enabled: true,
                    params: HashMap::from([("strokes".to_string(), serde_json::json!(strokes))]),
                },
                UiNode { id: "output".into(), node_type: "heeler.output".into(), enabled: true, params: HashMap::new() },
            ],
            connections: vec![
                UiConnection { from: ("src".into(), "out".into()), to: ("crop".into(), "in".into()) },
                UiConnection { from: ("crop".into(), "out".into()), to: ("cl".into(), "in".into()) },
                UiConnection { from: ("cl".into(), "out".into()), to: ("output".into(), "in".into()) },
            ],
        };
        let (out, actual) = inject_roi_px(&ui, [0.5, 0.5, 0.2, 0.2], None).unwrap();
        // Grown toward the source of what the stroke lays in the rect
        // (its footprint, 0.55 to 0.65, read 0.2 left and 0.1 down), and
        // no further: the viewport's other edges stay put.
        assert!((actual[0] - 0.35).abs() < 1e-9, "x grew to the source: {actual:?}");
        assert!((actual[1] - 0.5).abs() < 1e-9, "y kept the viewport's top: {actual:?}");
        assert!((actual[0] + actual[2] - 0.7).abs() < 1e-9, "{actual:?}");
        assert!((actual[1] + actual[3] - 0.75).abs() < 1e-9, "y grew to the source: {actual:?}");
        // And the clone node was handed the rect it must map through.
        let cl = out.nodes.iter().find(|n| n.id == "cl").unwrap();
        assert_eq!(cl.params.get("roi_x").and_then(|v| v.as_f64()), Some(actual[0]));
        // A heal over the whole picture solves over all of it, so the
        // patch would be the frame: not worth patching at all.
        let far = r#"[{"points":[[0.5,0.5]],"radius":0.5,"src_dx":0.1,"src_dy":0.1,"heal":true}]"#;
        let mut wide = ui;
        wide.nodes[2].params.insert("strokes".into(), serde_json::json!(far));
        assert!(inject_roi_px(&wide, [0.5, 0.5, 0.2, 0.2], None).is_none());
    }

    #[test]
    fn roi_rect_validation_rejects_the_useless_and_fixes_the_wild() {
        assert_eq!(valid_roi(None), None);
        assert_eq!(valid_roi(Some(vec![0.0, 0.0, 1.0, 1.0])), None, "full frame is not an ROI");
        assert_eq!(valid_roi(Some(vec![0.1, 0.2])), None, "wrong arity");
        let r = valid_roi(Some(vec![-0.5, 0.9, 4.0, 0.5])).unwrap();
        assert!(r[0] >= 0.0 && r[0] + r[2] <= 1.0 && r[1] + r[3] <= 1.0);
    }

    /// The same field case, but through the LITERAL payload the frontend
    /// produces: the owner's saved graph run through replace_graph, the
    /// profile upgrade, and the Curves section switch in the real reducer,
    /// then serializeGraph. If this passes and the app still picks
    /// mid-axis, the break is in the IPC plumbing, not the logic.
    #[test]
    fn curve_pick_sample_survives_the_exact_frontend_payload() {
        let payload: serde_json::Value =
            serde_json::from_str(include_str!("../fixtures/curve_pick_payload.json")).unwrap();
        let ui: UiGraph = serde_json::from_value(payload["graph"].clone()).unwrap();
        let registry = Registry::builtin();
        let g = build_graph(&ui, &registry).unwrap();
        // Resolution happens against the received graph, the way the
        // command does it: from the curve node, not a frontend guess.
        let term = curve_sample_terminal(&ui, &g, "curves").expect("resolvable terminal");
        assert_eq!(term, "bend", "the curve's feeder in this payload is the disabled bend");
        let mut sources = HashMap::new();
        let bright = Arc::new(ImageBuf::filled(4, 4, [0.4, 0.4, 0.42, 1.0]));
        for n in ui
            .nodes
            .iter()
            .filter(|n| n.node_type == "heeler.image_source" || n.node_type == "heeler.group")
        {
            sources.insert(n.id.clone(), SourceImage { image: bright.clone(), version: 1, measured: false });
        }
        let mut exec = Executor::new();
        let out = exec.render(&g, &term, &sources).unwrap();
        let img = out.as_image().unwrap();
        let s = sample_patch(img, 0.0, 0.0, 0.01);
        assert!(
            s.luma_linear > 0.9,
            "the profiled render must sample bright, got {}",
            s.luma_linear
        );
    }

    /// The owner's field case, end to end on the engine side: an old saved
    /// graph (bend disabled by migration) gains a curves node from the
    /// section switch, the picker asks for the value feeding curves, and
    /// that value must carry the whole develop chain. A blown sky at +3 EV
    /// picks near the top of the axis, not the middle.
    #[test]
    fn curve_pick_sample_reads_the_developed_frame_through_a_disabled_feeder() {
        let node = |id: &str, ty: &str, enabled: bool, params: Vec<(&str, serde_json::Value)>| UiNode {
            id: id.into(),
            node_type: ty.into(),
            enabled,
            params: params.into_iter().map(|(k, v)| (k.to_string(), v)).collect(),
        };
        let wire = |a: &str, b: &str| UiConnection {
            from: (a.into(), "out".into()),
            to: (b.into(), "in".into()),
        };
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                node("src", "heeler.image_source", true, vec![]),
                node("exposure", "heeler.exposure", true, vec![("exposure", serde_json::json!(3.0))]),
                node(
                    "profile",
                    "heeler.tone_profile",
                    true,
                    vec![("baseline_ev", serde_json::json!(1.3)), ("shadow_toe", serde_json::json!(50.0))],
                ),
                // Disabled, exactly how migrateGraph ships it into old graphs.
                node("bend", "heeler.color_bend", false, vec![]),
                node("curves", "heeler.curves", true, vec![]),
                node("output", "heeler.output", true, vec![]),
            ],
            connections: vec![
                wire("src", "exposure"),
                wire("exposure", "profile"),
                wire("profile", "bend"),
                wire("bend", "curves"),
                wire("curves", "output"),
            ],
        };
        let registry = Registry::builtin();
        let g = build_graph(&ui, &registry).unwrap();
        // The resolver lands on the disabled bend node, which must stay
        // addressable and render as its input.
        assert_eq!(curve_sample_terminal(&ui, &g, "curves").as_deref(), Some("bend"));
        // A curve node the graph has never heard of (a synthesized layer
        // tool) degrades to the graph terminal, never to nothing.
        assert_eq!(curve_sample_terminal(&ui, &g, "layer_1_curves").as_deref(), Some("output"));
        let mut sources = HashMap::new();
        // A sky just under clipping before the +3 EV push.
        sources.insert(
            "src".to_string(),
            SourceImage { image: Arc::new(ImageBuf::filled(4, 4, [0.4, 0.4, 0.42, 1.0])), version: 1, measured: false },
        );
        let mut exec = Executor::new();
        let out = exec.render(&g, "bend", &sources).unwrap();
        let img = out.as_image().unwrap();
        let s = sample_patch(img, 0.0, 0.0, 0.01);
        assert!(
            s.luma_linear > 0.95,
            "a +3 EV sky must sample at the top of the curve axis, got {}",
            s.luma_linear
        );
    }

    fn render_ui_node(node_type: &str, params: &[(&str, serde_json::Value)]) -> ImageBuf {
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                UiNode {
                    id: "n".into(),
                    node_type: node_type.into(),
                    enabled: true,
                    params: params.iter().map(|(k, v)| (k.to_string(), v.clone())).collect(),
                },
            ],
            connections: vec![UiConnection { from: ("src".into(), "out".into()), to: ("n".into(), "in".into()) }],
        };
        let registry = Registry::builtin();
        let g = build_graph(&ui, &registry).unwrap();
        let mut sources = HashMap::new();
        sources.insert("src".to_string(), SourceImage { image: gradient_source(), version: 1, measured: false });
        let mut exec = Executor::new();
        let out = exec.render(&g, "n", &sources).unwrap();
        (**out.as_image().unwrap()).clone()
    }

    /// The controls that are not plain sliders: text params, paired
    /// wheels, and the one that changes dimensions. Sliders are covered
    /// by every_develop_slider_moves_the_image_under_its_ui_name, which
    /// drives them under the names the UI actually sends.
    #[test]
    fn every_ui_control_reaches_the_engine() {
        // Dimension-changing control asserts dims specifically.
        let cropped = render_ui_node("heeler.crop_rotate", &[("crop_w", serde_json::json!(0.5))]);
        assert_eq!(cropped.width, 4);
        // Curves via the text param path, including the luminosity channel.
        let curved = render_ui_node(
            "heeler.curves",
            &[("points", serde_json::json!(r#"{"luma":[[0,0],[0.5,0.3],[1,1]]}"#))],
        );
        assert!(curved.data != render_ui_node("heeler.curves", &[]).data, "luma curve disconnected");

        // Wheel hue only means something once the puck leaves the center,
        // so hue is a paired control: angle plus distance.
        let pushed = render_ui_node(
            "heeler.color_balance",
            &[("midtones_hue", serde_json::json!(120.0)), ("midtones_sat", serde_json::json!(80.0))],
        );
        let other_hue = render_ui_node(
            "heeler.color_balance",
            &[("midtones_hue", serde_json::json!(0.0)), ("midtones_sat", serde_json::json!(80.0))],
        );
        assert!(pushed.data != other_hue.data, "wheel hue disconnected");
        assert!(
            pushed.data != render_ui_node("heeler.color_balance", &[]).data,
            "wheel push disconnected"
        );

        // Text-param controls: profile mode and channel selection.
        let filmic = render_ui_node("heeler.tone_profile", &[("mode", serde_json::json!("film"))]);
        let linear = render_ui_node("heeler.tone_profile", &[("mode", serde_json::json!("linear"))]);
        assert!(filmic.data != linear.data, "tone profile mode disconnected");
        let red = render_ui_node("heeler.channel_extract", &[("channel", serde_json::json!("r"))]);
        let blue = render_ui_node("heeler.channel_extract", &[("channel", serde_json::json!("b"))]);
        assert!(red.data != blue.data, "channel selection disconnected");
    }

    fn render_ui_node_ctx(
        node_type: &str,
        ctx: &[(&str, f64)],
        extra: Option<(&str, f64)>,
    ) -> ImageBuf {
        let mut params: Vec<(&str, serde_json::Value)> =
            ctx.iter().map(|(k, v)| (*k, serde_json::json!(v))).collect();
        if let Some((k, v)) = extra {
            params.retain(|(n, _)| *n != k);
            params.push((k, serde_json::json!(v)));
        }
        render_ui_node(node_type, &params)
    }

