    #[test]
    fn a_parked_render_lock_is_retaken_after_a_panic() {
        let _held = RenderLockHeld::hold(render_lock().blocking_lock());
        assert!(std::panic::catch_unwind(|| outside_render_lock(|| panic!("test unwind"))).is_err());
        assert!(HELD_RENDER_LOCK.with(|h| h.borrow().is_some()));
        assert!(render_lock().try_lock().is_err());
    }

    /// The render lock really is let go while a merge runs, and taken
    /// back after.
    #[test]
    fn a_stack_merge_lets_the_render_lock_go() {
        let _held = RenderLockHeld::hold(render_lock().blocking_lock());
        let (tx, rx) = std::sync::mpsc::channel();
        outside_render_lock(|| {
            std::thread::spawn(move || {
                let _g = render_lock().blocking_lock();
                tx.send(()).unwrap();
            });
            rx.recv_timeout(std::time::Duration::from_secs(10)).expect("another render took the lock while the merge ran");
        });
        assert!(HELD_RENDER_LOCK.with(|h| h.borrow().is_some()), "taken back after");
    }

    #[test]
    fn a_panicked_merge_removes_only_its_own_gate() {
        let key = "test-panicked-merge-gate";
        let result = std::panic::catch_unwind(|| one_at_a_time(key, || panic!("test merge panic")));
        assert!(result.is_err());
        assert!(!recipe_gates().lock().unwrap_or_else(|e| e.into_inner()).contains_key(key));
        assert_eq!(one_at_a_time(key, || 42), 42);
    }

    /// A second request for the same merge waits for the first rather
    /// than running beside it.
    #[test]
    fn one_merge_per_identity_at_a_time() {
        let running = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let peak = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let threads: Vec<_> = (0..4)
            .map(|_| {
                let (running, peak) = (running.clone(), peak.clone());
                std::thread::spawn(move || {
                    one_at_a_time("test-identity", || {
                        let now = running.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
                        peak.fetch_max(now, std::sync::atomic::Ordering::SeqCst);
                        std::thread::sleep(std::time::Duration::from_millis(20));
                        running.fetch_sub(1, std::sync::atomic::Ordering::SeqCst);
                    })
                })
            })
            .collect();
        for t in threads {
            t.join().unwrap();
        }
        assert_eq!(peak.load(std::sync::atomic::Ordering::SeqCst), 1);
    }

    /// The manifest is the thing the user keeps, so it has to survive a
    /// round trip and tolerate an older file that predates a field.
    #[test]
    fn stack_manifests_round_trip_and_tolerate_missing_fields() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("s.stack");
        let m = StackManifest {
            version: 1,
            mode: "hdr".into(),
            align: true,
            members: vec!["one.NEF".into(), "two.NEF".into()],
        };
        write_stack(&path, &m).unwrap();
        let back = read_stack(&path).unwrap();
        assert_eq!(back.members, m.members);
        assert_eq!(back.mode, "hdr");

        // A manifest written before `align` existed still loads, aligned
        // by default rather than refusing to open.
        std::fs::write(&path, br#"{"mode":"mean","members":["x.png"]}"#).unwrap();
        let old = read_stack(&path).unwrap();
        assert!(old.align);
        assert_eq!(old.version, 1);
    }

    /// The bend has to change the picture when driven the way the UI
    /// drives it: through build_graph, with the UI's own param names,
    /// against a real chain. The op's own tests pass on a node built by
    /// hand, which says nothing about whether the app's values arrive.
    #[test]
    fn bend_changes_the_render_through_the_ui_bridge() {
        let bend = |dst_hue: f64| {
            let ui = UiGraph {
                graph_id: "t".into(),
                nodes: vec![
                    UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                    UiNode {
                        id: "bend".into(),
                        node_type: "heeler.color_bend".into(),
                        enabled: true,
                        params: HashMap::from([
                            ("src_hue".to_string(), serde_json::json!(30.0)),
                            ("src_sat".to_string(), serde_json::json!(0.6)),
                            ("dst_hue".to_string(), serde_json::json!(dst_hue)),
                            ("dst_sat".to_string(), serde_json::json!(0.6)),
                            ("falloff".to_string(), serde_json::json!(0.9)),
                            ("amount".to_string(), serde_json::json!(100.0)),
                        ]),
                    },
                ],
                connections: vec![UiConnection {
                    from: ("src".into(), "out".into()),
                    to: ("bend".into(), "in".into()),
                }],
            };
            let registry = Registry::builtin();
            let g = build_graph(&ui, &registry).unwrap();
            let mut sources = HashMap::new();
            sources.insert("src".to_string(), SourceImage { image: gradient_source(), version: 1, measured: false });
            let mut exec = Executor::new();
            let out = exec.render(&g, "bend", &sources).unwrap();
            (**out.as_image().unwrap()).clone()
        };
        let still = bend(30.0); // destination on the source: no movement
        let moved = bend(150.0); // swung well round the disc
        assert!(
            still.data != moved.data,
            "dragging the destination changed nothing: the bend never reached the engine"
        );
    }

    /// Flag params must survive the trip from the UI. The registry types
    /// `invert` as a bool, the UI sends a JSON boolean, and build_graph
    /// used to match only numbers and strings: the flag fell through every
    /// arm and vanished, so the invert switch did nothing at all.
    #[test]
    fn boolean_flag_params_reach_the_engine() {
        let mask = |invert: serde_json::Value| {
            let ui = UiGraph {
                graph_id: "t".into(),
                nodes: vec![
                    UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                    UiNode {
                        id: "m".into(),
                        node_type: "heeler.range_mask".into(),
                        enabled: true,
                        params: HashMap::from([
                            ("luma_low".to_string(), serde_json::json!(0.5)),
                            ("luma_high".to_string(), serde_json::json!(1.0)),
                            ("invert".to_string(), invert),
                        ]),
                    },
                ],
                connections: vec![UiConnection {
                    from: ("src".into(), "out".into()),
                    to: ("m".into(), "in".into()),
                }],
            };
            let registry = Registry::builtin();
            let g = build_graph(&ui, &registry).unwrap();
            let mut sources = HashMap::new();
            sources.insert("src".to_string(), SourceImage { image: gradient_source(), version: 1, measured: false });
            let mut exec = Executor::new();
            let out = exec.render(&g, "m", &sources).unwrap();
            let m = out.as_mask().unwrap();
            (m.value(0, 0), m.value(7, 7))
        };

        let (dark, bright) = mask(serde_json::json!(false));
        assert!(bright > dark, "bright corner is inside the luma window");
        let (idark, ibright) = mask(serde_json::json!(true));
        assert!(ibright < idark, "inverted, the selection flips");
        assert!((ibright - (1.0 - bright)).abs() < 1e-6);
        assert!((idark - (1.0 - dark)).abs() < 1e-6);
    }

    /// The clip wire survives ingest.
    ///
    /// Regression for the owner's report: "I painted white pixels on
    /// Pixel 1, created Pixel 2, clipped it, painted green -- the green
    /// did not clip." The op was right and its unit test passed, but
    /// the wire targeted the blend's MASK port, which is Mask-kind;
    /// connect rejected the image and the `let _ =` swallowed the
    /// rejection, so clipping worked everywhere except in the running
    /// app. This test sits at the layer that failed: the serialized
    /// graph, through build_graph, into a render.
    #[test]
    fn a_clip_wire_survives_ingest_and_clips() {
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                // The base: paint on the left half only.
                UiNode {
                    id: "p1".into(),
                    node_type: "heeler.paint".into(),
                    enabled: true,
                    params: HashMap::from([(
                        "strokes".to_string(),
                        serde_json::json!(r##"[{"points":[[0.25,0.5]],"radius":0.25,"hardness":1.0,"flow":1.0,"color":"#ffffff"}]"##),
                    )]),
                },
                // The clipped layer: green everywhere.
                UiNode {
                    id: "p2".into(),
                    node_type: "heeler.paint".into(),
                    enabled: true,
                    params: HashMap::from([(
                        "strokes".to_string(),
                        serde_json::json!(r##"[{"points":[[0.5,0.5]],"radius":0.9,"hardness":1.0,"flow":1.0,"color":"#00ff00"}]"##),
                    )]),
                },
                UiNode {
                    id: "b2".into(),
                    node_type: "heeler.blend".into(),
                    enabled: true,
                    params: HashMap::from([("clip".to_string(), serde_json::json!(true))]),
                },
            ],
            connections: vec![
                UiConnection { from: ("src".into(), "out".into()), to: ("p1".into(), "in".into()) },
                UiConnection { from: ("src".into(), "out".into()), to: ("p2".into(), "in".into()) },
                UiConnection { from: ("src".into(), "out".into()), to: ("b2".into(), "in".into()) },
                UiConnection { from: ("p2".into(), "out".into()), to: ("b2".into(), "in2".into()) },
                // The clipping mask: the base content into the clip port.
                UiConnection { from: ("p1".into(), "out".into()), to: ("b2".into(), "clip".into()) },
            ],
        };
        let registry = Registry::builtin();
        let g = build_graph(&ui, &registry).unwrap();
        // The wire itself survived: this is the assertion that failed
        // silently the first time.
        assert!(
            g.connections().iter().any(|c| c.from.0 == "p1" && c.to.0 == "b2" && c.to.1 == "clip"),
            "the clip connection was dropped at ingest"
        );
        let mut sources = HashMap::new();
        sources.insert("src".to_string(), SourceImage { image: gradient_source(), version: 1, measured: false });
        let mut exec = Executor::new();
        let out = exec.render(&g, "b2", &sources).unwrap();
        let img = out.as_image().unwrap().clone();
        let plain = exec.render(&g, "src", &sources).unwrap();
        let src_img = plain.as_image().unwrap();
        let (w, h) = (img.width, img.height);
        // Where the base has paint, the green lands; where it does not,
        // the pixel is EXACTLY the photograph, because a clipped blend
        // outside its base must change nothing at all.
        let inside = img.pixel(w / 4, h / 2);
        let inside_src = src_img.pixel(w / 4, h / 2);
        assert!(
            inside[1] > inside_src[1] + 0.1,
            "green shows inside the base's pixels: {inside:?} vs {inside_src:?}"
        );
        let outside = img.pixel((w * 3) / 4, h / 2);
        let outside_src = src_img.pixel((w * 3) / 4, h / 2);
        for c in 0..3 {
            assert!(
                (outside[c] - outside_src[c]).abs() < 1e-5,
                "outside the base the photograph is untouched: {outside:?} vs {outside_src:?}"
            );
        }
    }

    /// The wheels' tonal ranges follow what is still to come: the main
    /// chain's Exposure and the profile's baseline, but not a layer's
    /// masked Exposure, and nothing past the profile.
    #[test]
    fn wheels_are_stamped_with_the_brightness_below_them() {
        let node = |id: &str, t: &str, enabled: bool, p: &[(&str, f64)]| UiNode {
            id: id.into(),
            node_type: t.into(),
            enabled,
            params: p.iter().map(|(k, v)| (k.to_string(), serde_json::json!(v))).collect(),
        };
        let wire = |a: &str, b: &str, port: &str| UiConnection { from: (a.into(), "out".into()), to: (b.into(), port.into()) };
        let ui = UiGraph {
            graph_id: "t".into(),
            nodes: vec![
                node("src", "heeler.image_source", true, &[]),
                node("cbal", "heeler.color_balance", true, &[("range_ev", 9.0)]),
                node("exposure", "heeler.exposure", true, &[("exposure", 0.5)]),
                node("layer_1_adj", "heeler.exposure", true, &[("exposure", 2.0)]),
                node("layer_1_mask", "heeler.radial_mask", true, &[]),
                node("layer_1_wheels", "heeler.color_balance", true, &[]),
                node("off", "heeler.exposure", false, &[("exposure", 3.0)]),
                node("profile", "heeler.tone_profile", true, &[("baseline_ev", 1.3)]),
                node("late", "heeler.exposure", true, &[("exposure", 4.0)]),
                node("split", "heeler.split_tone", true, &[]),
            ],
            connections: vec![
                wire("src", "cbal", "in"),
                wire("cbal", "exposure", "in"),
                wire("exposure", "layer_1_adj", "in"),
                wire("layer_1_mask", "layer_1_adj", "mask"),
                wire("layer_1_adj", "layer_1_wheels", "in"),
                wire("layer_1_wheels", "off", "in"),
                wire("off", "profile", "in"),
                wire("profile", "late", "in"),
                wire("late", "split", "in"),
            ],
        };
        let g = build_graph(&ui, &Registry::builtin()).unwrap();
        let ev = |id: &str| match g.node(id).unwrap().params.get("range_ev") {
            Some(ParamValue::Number(v)) => *v,
            other => panic!("{id} carries no range_ev: {other:?}"),
        };
        // A value arriving from the UI is replaced, never trusted.
        assert!((ev("cbal") - 1.8).abs() < 1e-9, "main Exposure and the baseline, not the layer's: {}", ev("cbal"));
        assert!((ev("layer_1_wheels") - 1.3).abs() < 1e-9, "a layer's wheels see the baseline alone: {}", ev("layer_1_wheels"));
        assert!(ev("split").abs() < 1e-9, "past the profile nothing is still to come: {}", ev("split"));
    }

