    #[test]
    fn the_model_store_move_copies_then_removes() {
        let from_root = tempfile::tempdir().unwrap();
        let to_root = tempfile::tempdir().unwrap();
        let from = from_root.path();
        let to = to_root.path();
        // Two installed models, a smart-mask raster, and an interrupted
        // download's staging dir at the old home.
        let sam = heeler_vision::model_dir(from, &heeler_vision::MOBILE_SAM);
        let lama = heeler_vision::model_dir(from, &heeler_vision::LAMA);
        std::fs::create_dir_all(&sam).unwrap();
        std::fs::create_dir_all(&lama).unwrap();
        std::fs::write(sam.join("encoder.onnx"), b"sam-bytes").unwrap();
        std::fs::write(lama.join("model.onnx"), b"lama-bytes").unwrap();
        std::fs::create_dir_all(from.join("smartmasks")).unwrap();
        std::fs::write(from.join("smartmasks").join("aa.png"), b"mask").unwrap();
        std::fs::create_dir_all(from.join("models").join(".lama.staging")).unwrap();
        std::fs::write(from.join("models").join(".lama.staging").join("archive.zip"), b"partial").unwrap();

        let (moved, bytes) = move_model_store(from, to).unwrap();
        assert_eq!(moved, vec!["mobile_sam", "lama"]);
        assert_eq!(bytes, 9 + 10);
        assert_eq!(std::fs::read(heeler_vision::model_dir(to, &heeler_vision::MOBILE_SAM).join("encoder.onnx")).unwrap(), b"sam-bytes");
        assert_eq!(std::fs::read(heeler_vision::model_dir(to, &heeler_vision::LAMA).join("model.onnx")).unwrap(), b"lama-bytes");
        assert!(!sam.exists() && !lama.exists(), "old copies are removed after a verified copy");
        // Nothing else under the old path was touched.
        assert_eq!(std::fs::read(from.join("smartmasks").join("aa.png")).unwrap(), b"mask");
        assert!(from.join("models").join(".lama.staging").join("archive.zip").exists());
    }

    #[test]
    fn a_partway_move_failure_leaves_both_copies() {
        let from_root = tempfile::tempdir().unwrap();
        let to_root = tempfile::tempdir().unwrap();
        let from = from_root.path();
        let to = to_root.path();
        let sam = heeler_vision::model_dir(from, &heeler_vision::MOBILE_SAM);
        std::fs::create_dir_all(&sam).unwrap();
        std::fs::write(sam.join("encoder.onnx"), b"sam-bytes").unwrap();
        // A FILE where the copy needs a directory: the copy must fail.
        std::fs::write(to.join("models"), b"in the way").unwrap();

        let err = move_model_store(from, to).unwrap_err();
        assert!(err.contains("both copies are on disk"), "the failure says so: {err}");
        assert_eq!(std::fs::read(sam.join("encoder.onnx")).unwrap(), b"sam-bytes", "the old copy stays");
    }

