    /// invert_mask's input arrives under two names: recipes write the
    /// registry's own "mask", and a wire tail-dragged out of the card's
    /// input dot lands as "in". Both must reach the engine's mask port,
    /// or the dragged spelling draws a wire that does nothing.
    #[test]
    fn both_spellings_of_invert_masks_input_reach_its_port() {
        for port in ["mask", "in"] {
            let ui = UiGraph {
                graph_id: "t".into(),
                nodes: vec![
                    UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                    UiNode { id: "lum".into(), node_type: "heeler.luminance_extract".into(), enabled: true, params: HashMap::new() },
                    UiNode { id: "inv".into(), node_type: "heeler.invert_mask".into(), enabled: true, params: HashMap::new() },
                ],
                connections: vec![
                    UiConnection { from: ("src".into(), "out".into()), to: ("lum".into(), "in".into()) },
                    UiConnection { from: ("lum".into(), "out".into()), to: ("inv".into(), port.into()) },
                ],
            };
            let registry = Registry::builtin();
            let g = build_graph(&ui, &registry).unwrap();
            assert!(
                g.incoming("inv", "mask").is_some(),
                "the {port} spelling must land on invert_mask's mask port"
            );
        }
    }

    /// Regression for "exposure stopped working": an unpainted brush mask
    /// wired into a node's mask port must not gate that node to zero.
    #[test]
    fn empty_brush_mask_does_not_neutralize_its_target() {
        let make = |exposure: f64| {
            let ui = UiGraph {
                graph_id: "t".into(),
                nodes: vec![
                    UiNode { id: "src".into(), node_type: "heeler.image_source".into(), enabled: true, params: HashMap::new() },
                    UiNode {
                        id: "e".into(),
                        node_type: "heeler.exposure".into(),
                        enabled: true,
                        params: HashMap::from([("exposure".to_string(), serde_json::json!(exposure))]),
                    },
                    UiNode {
                        id: "brush".into(),
                        node_type: "heeler.brush_mask".into(),
                        enabled: true,
                        params: HashMap::from([("strokes".to_string(), serde_json::json!("[]"))]),
                    },
                ],
                connections: vec![
                    UiConnection { from: ("src".into(), "out".into()), to: ("e".into(), "in".into()) },
                    UiConnection { from: ("src".into(), "out".into()), to: ("brush".into(), "in".into()) },
                    UiConnection { from: ("brush".into(), "out".into()), to: ("e".into(), "mask".into()) },
                ],
            };
            let registry = Registry::builtin();
            let g = build_graph(&ui, &registry).unwrap();
            let mut sources = HashMap::new();
            sources.insert("src".to_string(), SourceImage { image: gradient_source(), version: 1, measured: false });
            let mut exec = Executor::new();
            let out = exec.render(&g, "e", &sources).unwrap();
            (**out.as_image().unwrap()).clone()
        };
        let base = make(0.0);
        let brightened = make(1.5);
        assert!(base.data != brightened.data, "empty brush mask silently disabled exposure");
    }

    /// The gesture tier's downscale runs inside render_preview's zero-size
    /// job and must pay for its own frame: bare, a 1024 frame was refused
    /// with "0 MiB available" and the drag fell into the
    /// re-decode-every-frame retry (2026-09-09).
    #[test]
    fn the_gesture_tier_downscale_pays_for_its_frame_inside_the_zero_size_preview_job() {
        let src = ImageBuf::filled(2048, 1365, [0.3, 0.4, 0.5, 1.0]);
        memory::with_budget(64 << 30, || {
            let _outer = Job::admit(0, "preview").unwrap();
            let bare = memory::catch(|| downscale(&src, 1024));
            assert!(bare.is_err(), "the bare downscale is exactly the refusal this guards against");
            let paid = downscale_admitted(&src, 1024).expect("the admitted downscale");
            assert_eq!(paid.width, 1024);
        });
    }

    /// Planting decodes a raster from disk inside render_preview's
    /// zero-size job; the decode must pay for its own frame.
    #[test]
    fn a_planted_raster_decodes_inside_the_zero_size_preview_job() {
        let mut img = ImageBuf::new(1024, 683);
        for px in img.data.chunks_mut(4) {
            px.copy_from_slice(&[0.3, 0.4, 0.5, 1.0]);
        }
        let bytes = heeler_io::encode_png16_raw(&img).unwrap();
        memory::with_budget(64 << 30, || {
            let _outer = Job::admit(0, "preview").unwrap();
            let r = memory::catch(|| heeler_io::decode_png_raw(&bytes));
            match r {
                Ok(Ok(d)) => assert_eq!((d.width, d.height), (1024, 683)),
                Ok(Err(e)) => panic!("decode error: {e}"),
                Err(e) => panic!("memory refusal: {e}"),
            }
        });
    }

    /// The model-denoise raster is keyed by photograph, source
    /// options    /// The model-denoise raster is keyed by
