    #[test]
    fn full_denoise_disk_status_survives_sessions_and_checks_current_identity_and_clear() {
        let temp = tempfile::tempdir().unwrap();
        let fingerprint = "photo|wb1|mat1|hl0|dq-1|raw:icc-v1:dng-exposure-v2|g0";
        let revision = 42;
        let version = denoise_version(revision, fingerprint, 32, 16);
        assert!(!denoise_full_status_at(temp.path(), revision, fingerprint, || None).full);
        persist_denoise_raster(temp.path(), version, &ImageBuf::filled(32, 16, [0.2,0.4,0.6,1.0])).unwrap();
        persist_denoise_full_record(temp.path(), revision, fingerprint, 32, 16).unwrap();
        // No Session or decoded image is involved in the next launch's answer.
        memory::with_budget(1, || {
            let status = denoise_full_status_at(temp.path(), revision, fingerprint, || panic!("receipt supplies dimensions"));
            assert!(status.full);
            assert_eq!(status.version, Some(format!("{version:016x}")));
        });
        assert!(!denoise_full_status_at(temp.path(), revision + 1, fingerprint, || None).full);
        assert!(!denoise_full_status_at(temp.path(), revision, &format!("{fingerprint}|changed-options"), || None).full);
        assert_eq!(clear_smart_rasters_in(&smart_raster_dir(temp.path())), 1);
        assert!(!denoise_full_status_at(temp.path(), revision, fingerprint, || panic!("receipt remains only metadata")).full);
    }

