    #[test]
    fn denoise_switch_diagnostic() {
        let temp = tempfile::tempdir().unwrap();
        let path = temp.path().join("diagnostic.dng");
        let source = ImageBuf::filled(64, 32, [0.4, 0.2, 0.1, 1.0]);
        std::fs::write(&path, heeler_io::encode_dng(&source, None).unwrap()).unwrap();
        let mut session = Session::default();
        session.paths.insert("photo".into(), path);
        let opts = heeler_io::RawSourceOpts::default();
        let first = source_version_key_in_session(&session, "photo", opts);
        let revision = denoise_model_revision(None);
        let calls = std::cell::Cell::new(0);
        let visit = |fingerprint: &str, edge| denoise_map_at(temp.path(), revision, fingerprint, 64, 32, edge,
            |version| { calls.set(calls.get() + 1); persist_denoise_raster(temp.path(), version, &source)?; Ok(1) },
            |line| eprintln!("DEBUG {line}"));
        assert_eq!(visit(&first, None).unwrap().work, "model");
        let _unrelated = source_version_key_in_session(&session, "other", opts);
        let back = source_version_key_in_session(&session, "photo", opts);
        assert_eq!(first, back);
        assert!(back.contains("dng-exposure-v4"));
        assert_eq!(visit(&back, Some(2048)).unwrap().work, "cached");
        assert_eq!(calls.get(), 1);
        memory::with_budget(1, || {
            let answer = denoise_map_at(temp.path(), revision, &back, 64, 32, None,
                |_| { calls.set(calls.get() + 1); Ok(1) }, |line| eprintln!("DEBUG low budget {line}")).unwrap();
            assert_eq!(answer.work, "cached", "presence checks must not decode the raster");
            assert_eq!(answer.tiles, 0);
            let version = denoise_version(revision, &back, 64, 32);
            let error = read_denoise_raster_checked(temp.path(), version, 64, 32).err().expect("refusal must reach export");
            assert!(memory::is_refusal(&error));
        });
        assert_eq!(calls.get(), 1);
    }

    #[test]
    fn a_full_denoise_request_never_substitutes_a_preview_on_failure() {
        let source = Arc::new(ImageBuf::new(4, 3));
        let result = denoise_source(None, |_| panic!("a preview must not stand in for full size"), || Err("source is offline".into()));
        assert_eq!(result.unwrap_err(), "source is offline");
        let preview = denoise_source(Some(64), |edge| { assert_eq!(edge, 64); Ok(source.clone()) }, || panic!("preview asked for full size")).unwrap();
        assert!(Arc::ptr_eq(&preview, &source));
    }

    #[test]
    fn a_poisoned_run_lock_still_admits_the_next_run() {
        // A refusal panic mid-run poisons the lock; the next run must
        // proceed. catch_unwind keeps the suite green; the one stderr
        // line is the proof the panic happened.
        let died = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _held = denoise_run_lock();
            panic!("a run died holding the noise reduction lock");
        }));
        assert!(died.is_err());
        let _next = denoise_run_lock();
    }


    #[test]
    fn denoise_map_routes_its_source_through_the_no_preview_rule() {
        // The command's body cannot run under a test runtime (the
        // commands are typed on the real window runtime, which needs
        // the main thread's event loop), so this pins the wiring in
        // the source text: denoise_map must take its source through
        // denoise_source, and no or_else fallback may appear in its
        // body. The policy itself is pinned by
        // a_full_denoise_request_never_substitutes_a_preview_on_failure.
        let src = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs")).unwrap();
        let start = src.find("async fn denoise_map(").unwrap();
        let body = &src[start..src[start..].find("\n}\n").unwrap() + start];
        assert!(body.contains("denoise_source(edge,"), "denoise_map must route through denoise_source");
        assert!(!body.contains("or_else"), "a preview fallback crept back into denoise_map");
    }

