    #[test]
    fn denoise_model_updates_change_cache_identity() {
        let dir = tempfile::tempdir().unwrap();
        let opts = heeler_io::RawSourceOpts::default();
        let mut session = Session::default();
        let before = test_denoise_version(session_denoise_revision(&mut session, Some(dir.path())), "img", opts, 64, 64);
        let model = heeler_vision::model_dir(dir.path(), &heeler_vision::SCUNET);
        std::fs::create_dir_all(&model).unwrap();
        std::fs::write(model.join("installed.json"), br#"{"version":"2027.01","files":[]}"#).unwrap();
        // The memo holds until the models are declared changed: a
        // render does not stat the model store, and after the drop the
        // new weights key a new answer.
        assert_eq!(test_denoise_version(session_denoise_revision(&mut session, Some(dir.path())), "img", opts, 64, 64), before);
        session.denoise_revision = None;
        let after = test_denoise_version(session_denoise_revision(&mut session, Some(dir.path())), "img", opts, 64, 64);
        assert_ne!(before, after);
        assert_eq!(after, test_denoise_version(session_denoise_revision(&mut session, Some(dir.path())), "img", opts, 64, 64));
    }

    #[test]
    fn denoise_pixel_cache_is_bounded_without_evicting_other_smart_tools() {
        let mut session = Session::default();
        let image = Arc::new(ImageBuf::new(4, 3));
        session.smart_rasters.insert("sam".into(), (image.clone(), 1));
        for i in 0..100 {
            cache_denoise_raster(&mut session, format!("denoise@{i}"), image.clone(), i);
        }
        assert!(session.smart_rasters.len() <= 9);
        assert!(session.smart_rasters.contains_key("sam"));
        assert!(session.smart_rasters.contains_key("denoise@99"));
        // A full-frame answer past the bound on its own is still kept,
        // alone: the render in hand reads it every frame.
        let big = Arc::new(ImageBuf::new(6000, 4000));
        cache_denoise_raster(&mut session, "denoise@big".into(), big, 7);
        assert!(session.smart_rasters.contains_key("denoise@big"));
        assert_eq!(session.smart_rasters.keys().filter(|k| k.starts_with("denoise@")).count(), 1);
    }

