    #[test]
    fn denoise_and_gesture_jobs_cover_overlapping_pixel_buffers() {
        let need = denoise_scratch_bytes(1024, 768).unwrap();
        // The metered terms, as literals: remetering the model means
        // updating heeler-vision's constants AND this line.
        assert_eq!(need, 1024 * 768 * 20 + 2011 * (1 << 20) * 5 / 4);
        memory::with_budget(need - 1, || assert!(Job::admit(need, "denoise").is_err()));
        assert!(denoise_scratch_bytes(usize::MAX, 2).is_err());
        let src = ImageBuf::new(64, 48);
        let need = downscale_scratch_bytes(64, 48, 63).unwrap();
        assert!(need >= 63 * 48 * 16 + 63 * 47 * 16);
        memory::with_budget(need - 1, || assert!(downscale_admitted(&src, 63).is_err()));
        memory::with_budget(need, || {
            let _outer = Job::admit(0, "preview").unwrap();
            assert_eq!(downscale_admitted(&src, 63).unwrap().width, 63);
        });
    }

    #[test]
    fn denoise_admission_refuses_in_words_just_below_and_admits_at_the_number() {
        let need = denoise_scratch_bytes(1024, 768).unwrap();
        memory::with_budget(need - 1, || {
            // Job is not Debug, so no unwrap_err: a pass here is a
            // panic, not a formatting error.
            let err = match admit_denoise_run(1024, 768) {
                Err(e) => e,
                Ok(_) => panic!("admitted one byte under the number"),
            };
            assert!(err.contains("noise reduction"), "the refusal should name itself: {err}");
        });
        memory::with_budget(need, || assert!(admit_denoise_run(1024, 768).is_ok()));
    }

    #[test]
    fn denoise_run_admission_reserves_the_metered_number_and_nothing_while_idle() {
        let (w, h) = (6000, 4000);
        let need = heeler_vision::denoise_run_reserve(w, h) as usize;
        memory::with_budget(need + 4096, || {
            let budget = memory::budget();
            assert_eq!(budget.external("noise model"), 0);
            assert_eq!(budget.snapshot().reserved, 0);
            let job = admit_denoise_run(w, h).expect("the metered run fits");
            assert_eq!(budget.snapshot().reserved, need);
            assert_eq!(budget.external("noise model"), 0);
            drop(job);
            assert_eq!(budget.snapshot().reserved, 0);
            assert_eq!(budget.external("noise model"), 0);
        });
    }

