        let mut ui = ui_graph();
        assert_eq!(source_opts_of(&ui), heeler_io::RawSourceOpts { camera_wb: true, camera_matrix: true, highlight: 0, demosaic: -1, ..Default::default() });
        ui.nodes[0]
