#[cfg(test)]
mod settle_identity_tests {
    use super::*;
    fn graph(kind: &str) -> UiGraph {
        serde_json::from_value(serde_json::json!({"graph_id":"own", "nodes":[
            {"id":"source","type":"heeler.image_source","enabled":true,"params":{}},
            {"id":"tool","type":kind,"enabled":true,"params":{}}
        ],"connections":[]})).unwrap()
    }
    #[test]
    fn settle_reuse_requires_audited_inputs() {
        assert_eq!(settle_source_identity(&graph("heeler.exposure"), "photo-v1"), Some("photo-v1".into()));
        // The recipe groups flatten to these and nothing external: the
        // Picture pass-through is a merge with one input.
        assert_eq!(settle_source_identity(&graph("heeler.merge"), "photo-v1"), Some("photo-v1".into()));
        for kind in ["heeler.smart_mask", "heeler.selection_mask", "heeler.matte_mask", "heeler.depth_map", "heeler.key_light", "heeler.model_denoise", "heeler.inpaint", "heeler.file", "heeler.catalog", "heeler.lut", "future.node"] {
            assert_eq!(settle_source_identity(&graph(kind), "photo-v1"), None, "{kind}");
        }
    }
    #[test]
    fn settle_identity_observes_source_replacement_and_recipe_generation() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("own.jpg");
        std::fs::write(&path, [1u8; 10]).unwrap();
        let identity = |generation| source_version_key_for_path(Some(path.clone()), "own", heeler_io::RawSourceOpts::default(), generation);
        let before = identity(0);
        std::fs::write(&path, [2u8; 20]).unwrap();
        assert_ne!(before, identity(0));
        assert_ne!(identity(0), identity(1));
    }
    #[test]
    fn a_moved_photograph_keeps_its_source_key() {
        // A relink keeps the image id and changes the path; the file's
        // length and modified time travel with it, so its decoded
        // pixels, depth plane and Model NR map are still its own.
        let dir = tempfile::tempdir().unwrap();
        let (a, b) = (dir.path().join("a"), dir.path().join("b"));
        std::fs::create_dir_all(&a).unwrap();
        std::fs::create_dir_all(&b).unwrap();
        std::fs::write(a.join("own.jpg"), [1u8; 10]).unwrap();
        let key = |p: PathBuf| source_version_key_for_path(Some(p), "own", heeler_io::RawSourceOpts::default(), 0);
        let before = key(a.join("own.jpg"));
        std::fs::rename(a.join("own.jpg"), b.join("own.jpg")).unwrap();
        assert_eq!(before, key(b.join("own.jpg")), "the same file in a new folder is the same source");
        std::fs::write(b.join("own.jpg"), [2u8; 20]).unwrap();
        assert_ne!(before, key(b.join("own.jpg")), "a replaced file is a new source");
    }
    #[test]
    fn a_disabled_external_node_does_not_keep_reuse_off() {
        let mut g = graph("heeler.file");
        assert_eq!(settle_source_identity(&g, "photo-v1"), None, "an enabled File node renders again");
        g.nodes.iter_mut().find(|n| n.node_type == "heeler.file").unwrap().enabled = false;
        assert_eq!(settle_source_identity(&g, "photo-v1"), Some("photo-v1".into()), "bypassed, it is a pass-through");
    }
    #[test]
    fn two_files_with_one_length_and_time_are_two_sources() {
        // A burst on a card with whole-second times: equal lengths and
        // equal modified times, different photographs. The head hash
        // tells them apart; a byte-identical copy reads as the same.
        let dir = tempfile::tempdir().unwrap();
        let (a, b, c) = (dir.path().join("a.jpg"), dir.path().join("b.jpg"), dir.path().join("c.jpg"));
        std::fs::write(&a, [1u8; 4096]).unwrap();
        std::fs::write(&b, [2u8; 4096]).unwrap();
        std::fs::write(&c, [1u8; 4096]).unwrap();
        let when = std::time::SystemTime::UNIX_EPOCH + std::time::Duration::from_secs(1_700_000_000);
        for p in [&a, &b, &c] {
            std::fs::File::options().write(true).open(p).unwrap().set_modified(when).unwrap();
        }
        let key = |p: &PathBuf| source_version_key_for_path(Some(p.clone()), "own", heeler_io::RawSourceOpts::default(), 0);
        assert_ne!(key(&a), key(&b), "different bytes under one length and time");
        assert_eq!(key(&a), key(&c), "the same bytes are the same source");
    }
    #[test]
    fn every_static_settle_type_is_registered() {
        let registry = Registry::builtin();
        for kind in SETTLE_STATIC_TYPES {
            assert!(registry.get(kind).is_some(), "{kind} is on the settle allowlist but is not a node type");
        }
    }
    #[test]
    fn a_reduced_frame_never_carries_the_settle_identity() {
        // The memory fallback's notice is said once per photograph; the
        // second reduced frame of the same photograph used to keep its
        // identity, and the pump remembered it as the full-resolution
        // settle.
        let seen = Mutex::new(std::collections::HashSet::new());
        let meta = || PreviewResult {
            source_identity: Some("photo-v1".into()),
            memory_notice: None,
            mime: "image/jpeg".into(),
            ms: 1,
            image_id: "img_1".into(),
            backend: "cpu".into(),
            roi: None,
            frame: None,
        };
        let refused = || Some("Preview reduced to 2048 pixels because memory".to_string());
        let mut first = meta();
        assert!(note_reduced_frame(&mut first, refused(), "/photos/a.RW2", &seen).is_some());
        assert_eq!((first.source_identity.as_deref(), first.memory_notice.is_some()), (None, true));
        let mut second = meta();
        assert!(note_reduced_frame(&mut second, refused(), "/photos/a.RW2", &seen).is_none(), "the notice is said once");
        assert_eq!((second.source_identity.as_deref(), second.memory_notice.as_deref()), (None, None));
        let mut whole = meta();
        assert!(note_reduced_frame(&mut whole, None, "/photos/a.RW2", &seen).is_none());
        assert_eq!(whole.source_identity.as_deref(), Some("photo-v1"), "a full frame keeps its identity");
    }
}

